type Step = (env: Envelope) => Promise<Envelope>;
const registry = { validate, reserve, charge } satisfies Record<string, Step>;
type StepId = keyof typeof registry;

async function advance(env: Envelope & { slip: StepId[]; cursor: number }) {
  while (env.cursor < env.slip.length) {
    await registry[env.slip[env.cursor]](env);   // typos are compile errors
    env.cursor += 1;
  }
  return env;
}
